import {all,put,remove,batch,dump,replaceAll,STORES,DB_VERSION} from './db.js';
import {STATUS,SOURCES,PRIORITIES,uid,today,stamp,date,money,esc,make,download,csv,phoneLink} from './core.js';
import {renderDMStudio,generateFromForm,copyDraft,saveDraftTemplate,recordDraft,syncDraftFromEditor} from './dm-studio.js';
const $=s=>document.querySelector(s), view=$('#view'), modalRoot=$('#modalRoot');let page='dashboard',mode='table',cache={},toastTimer;
const navItems=[['dashboard','◈','Dashboard'],['prospects','◎','Prospects'],['dmstudio','✦','DM Studio'],['followups','◷','Follow-ups'],['templates','▤','Templates'],['clients','♙','Clients & orders'],['finance','＄','Finance'],['analytics','⌁','Analytics'],['settings','⚙','Settings']];
function toast(msg){const n=$('#toast');n.textContent=msg;n.className='toast';clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.className='hidden',3000)}
function nav(){ $('#nav').innerHTML=navItems.map(([id,ic,n])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}">${ic}<span>${n}</span></button>`).join('');const item=navItems.find(x=>x[0]===page);$('#pageTitle').textContent=item?.[2]||'Dashboard';$('#crumb').textContent='KINGQAYUMEDITZ · WORKSPACE'}
async function load(){const data={};for(const s of STORES)data[s]=await all(s);cache=data;return data}
const empty=(title,sub,cta='')=>`<div class="empty"><b>${title}</b>${sub}${cta?`<div style="margin-top:14px"><button class="primary" data-action="${cta}">＋ Add new</button></div>`:''}</div>`;
function stat(label,value,note='From your saved records'){return `<div class="card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function dueList(data,limit=5){const list=data.followups.filter(x=>!x.completed&&!x.cancelled).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,limit);return list.length?`<div class="list">${list.map(f=>{const p=data.prospects.find(x=>x.id===f.prospectId);return `<div class="row"><div><div class="row-title">${esc(p?.name||'Deleted prospect')}</div><div class="row-sub">${date(f.dueDate)} · ${esc(f.reason||f.action||'Follow-up')}</div></div><div><button class="link-btn" data-action="complete-followup" data-id="${f.id}">Complete</button> <button class="link-btn" data-action="detail" data-id="${f.prospectId}">Open</button></div></div>`}).join('')}</div>`:empty('All clear','No upcoming follow-ups.')}
async function render(){try{const focusId=document.activeElement?.id,selection=focusId&&document.activeElement?.selectionStart, d=await load();nav();const renderers={dashboard:dashboard,prospects:prospects,dmstudio:renderDMStudio,followups:followups,templates:templates,clients:clients,finance:finance,analytics:analytics,settings:settings};view.innerHTML=(renderers[page]||dashboard)(d);if(focusId){const el=$('#'+CSS.escape(focusId));if(el){el.focus();if(selection!==undefined&&['text','search','tel','url',''].includes(el.type))el.setSelectionRange(selection,selection)}}}catch(e){view.innerHTML=empty('Could not load local data',esc(e.message));console.error(e)}}
function dashboard(d){const p=d.prospects,contacted=p.filter(x=>x.firstContactDate||['Contacted','Awaiting reply','Interested','Follow-up due','Negotiating','Won / client'].includes(x.status)),won=p.filter(x=>x.status==='Won / client'),due=d.followups.filter(x=>!x.completed&&!x.cancelled&&x.dueDate===today()).length,over=d.followups.filter(x=>!x.completed&&!x.cancelled&&x.dueDate<today()).length,received=d.interactions.filter(x=>x.type==='Reply received').length,interested=p.filter(x=>x.status==='Interested').length,paid=d.payments.reduce((s,x)=>s+(+x.amount||0),0),out=d.orders.filter(x=>x.status!=='cancelled').reduce((s,o)=>s+Math.max(0,(+o.price||0)-d.payments.filter(x=>x.orderId===o.id).reduce((a,x)=>a+(+x.amount||0),0)),0);const activity=[...d.interactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<div class="grid stats">${stat('Total prospects',p.length)}${stat('Contacted',contacted.length)}${stat('Replies received',received)}${stat('Interested',interested)}${stat('Follow-ups today',due)}${stat('Overdue follow-ups',over,'Needs attention')}${stat('Converted clients',won.length)}${stat('Received · outstanding',money(paid)+' · '+money(out),'Recorded payments and open balances')}</div><div class="grid cols"><section><div class="card"><div class="section-head" style="margin-top:0"><h2>Prospect pipeline</h2><button class="link-btn" data-page="prospects">View pipeline →</button></div><div class="pipeline">${['New prospect','Contacted','Interested','Won / client'].map(s=>`<div class="pipe"><span>${s}</span><b>${p.filter(x=>x.status===s).length}</b></div>`).join('')}</div></div><div class="section-head"><h2>Recent activity</h2><span class="subtle">Latest interactions</span></div><div class="card">${activity.length?`<div class="list">${activity.map(i=>`<div class="row"><div><div class="row-title">${esc(i.type)} · ${esc(d.prospects.find(p=>p.id===i.prospectId)?.name||'Prospect')}</div><div class="row-sub">${date(i.date)} · ${esc(i.summary||'')}</div></div></div>`).join('')}</div>`:empty('Your activity appears here','Log a message, reply, call, or quote from any prospect.')}</div></section><section><div class="section-head" style="margin-top:0"><h2>Upcoming follow-ups</h2><button class="link-btn" data-page="followups">See all →</button></div><div class="card">${dueList(d)}</div><div class="section-head"><h2>Recently added prospects</h2></div><div class="card">${p.length?`<div class="list">${[...p].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,4).map(x=>`<div class="row"><div><div class="row-title">${esc(x.name)}</div><div class="row-sub">${esc(x.category||'Uncategorised')} · ${date(x.createdAt.slice(0,10))}</div></div><button class="link-btn" data-action="detail" data-id="${x.id}">View</button></div>`).join('')}</div>`:empty('No prospects yet','Add your first business prospect.','quick-add')}</div></section></div>`}
function prospectsLegacy(d){const rows=d.prospects.filter(p=>{const q=($('#q')?.value||'').toLowerCase();return (!q||`${p.name} ${p.contactName||''}`.toLowerCase().includes(q))&&(!($('#fs')?.value)||p.status===$('#fs').value)&&(!($('#fp')?.value)||p.priority===$('#fp').value)&&(!($('#fr')?.value)||p.source===$('#fr').value)}).sort((a,b)=>({High:3,Medium:2,Low:1}[b.priority]-({High:3,Medium:2,Low:1}[a.priority])||String(a.nextFollowup||'9999').localeCompare(b.nextFollowup||'9999')));let content;if(mode==='kanban')content=`<div class="kanban">${['New prospect','Qualified','Contacted','Awaiting reply','Interested','Follow-up due','Negotiating','Won / client','Future opportunity'].map(s=>`<div class="kan-col"><h3>${s} · ${rows.filter(x=>x.status===s).length}</h3>${rows.filter(x=>x.status===s).map(x=>`<article class="kan-card"><button class="link-btn" data-action="detail" data-id="${x.id}">${esc(x.name)}</button><div class="row-sub">${esc(x.category||'')} · ${esc(x.priority)}</div><select data-status="${x.id}">${STATUS.map(v=>`<option ${v===x.status?'selected':''}>${esc(v)}</option>`).join('')}</select></article>`).join('')}</div>`).join('')}</div>`;else content=rows.length?`<div class="table-wrap"><table><thead><tr><th>Business</th><th>Status</th><th>Source</th><th>Priority</th><th>Next follow-up</th><th>Est. value</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="row-sub">${esc(x.contactName||x.category||'')}</div></td><td><span class="badge ${x.status==='Rejected'||x.status==='Not interested'?'red':''}">${esc(x.status)}</span></td><td>${esc(x.source||'—')}</td><td>${esc(x.priority||'—')}</td><td>${date(x.nextFollowup)}</td><td>${money(x.estimate)}</td><td><button class="link-btn" data-action="detail" data-id="${x.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching prospects','Try changing filters or add a prospect.','quick-add');return `<div class="toolbar"><input class="input search" id="q" placeholder="Search business or contact" value="${esc($('#q')?.value||'')}"><select id="fs"><option value="">All statuses</option>${STATUS.map(s=>`<option ${$('#fs')?.value===s?'selected':''}>${s}</option>`).join('')}</select><select id="fr"><option value="">All sources</option>${SOURCES.map(s=>`<option ${$('#fr')?.value===s?'selected':''}>${s}</option>`).join('')}</select><select id="fp"><option value="">Any priority</option>${PRIORITIES.map(s=>`<option ${$('#fp')?.value===s?'selected':''}>${s}</option>`).join('')}</select><div class="tabs"><button data-action="table" class="${mode==='table'?'active':''}">Table</button><button data-action="kanban" class="${mode==='kanban'?'active':''}">Pipeline</button></div></div>${content}`}
function followups(d){const active=d.followups.filter(x=>!x.completed&&!x.cancelled).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),done=d.followups.filter(x=>x.completed),groups=[['Overdue',active.filter(x=>x.dueDate<today())],['Due today',active.filter(x=>x.dueDate===today())],['Next 7 days',active.filter(x=>x.dueDate>today()&&x.dueDate<=new Date(Date.now()+7*86400000).toISOString().slice(0,10))],['Scheduled later',active.filter(x=>x.dueDate>new Date(Date.now()+7*86400000).toISOString().slice(0,10))],['Completed',done]];return groups.map(([title,items])=>`<div class="section-head"><h2>${title}</h2><span class="subtle">${items.length}</span></div><div class="card">${items.length?`<div class="list">${items.map(f=>`<div class="row"><div><div class="row-title">${esc(d.prospects.find(p=>p.id===f.prospectId)?.name||'Prospect')} <span class="badge ${!f.completed&&f.dueDate<today()?'red':''}">${date(f.dueDate)}</span></div><div class="row-sub">${esc(f.reason||'Follow-up')} · ${esc(f.action||'')}</div></div><div>${f.completed?'Completed':`<button class="link-btn" data-action="complete-followup" data-id="${f.id}">Complete</button> <button class="link-btn" data-action="reschedule" data-id="${f.id}">Reschedule</button> <button class="link-btn" data-action="cancel-followup" data-id="${f.id}">Cancel</button>`} <button class="link-btn" data-action="detail" data-id="${f.prospectId}">Open</button></div></div>`).join('')}</div>`:empty('Nothing here','Follow-ups you create will appear in this list.')}</div>`).join('')}
function templates(d){return `<div class="section-head"><div><h2>Message library</h2><span class="subtle">Templates are copied by you; nothing is sent automatically.</span></div><button class="primary" data-action="new-template">＋ New template</button></div>${d.templates.length?`<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${d.templates.map(t=>`<article class="card"><span class="badge">${esc(t.category||'Custom')}</span><div class="row-title" style="margin:12px 0">${esc(t.name)}</div><div class="row-sub" style="min-height:45px">${esc(t.body.slice(0,110))}${t.body.length>110?'…':''}</div><div class="row"><button class="link-btn" data-action="edit-template" data-id="${t.id}">Edit</button><button class="link-btn" data-action="duplicate-template" data-id="${t.id}">Duplicate</button><button class="link-btn" data-action="delete-template" data-id="${t.id}">Delete</button></div></article>`).join('')}</div>`:empty('No templates yet','Add your reusable, respectful outreach messages.','new-template')}`}
function legacyClients(d){const balance=o=>Math.max(0,+o.price-d.payments.filter(p=>p.orderId===o.id).reduce((s,p)=>s+(+p.amount||0),0));return `<div class="section-head"><div><h2>Clients and active orders</h2><span class="subtle">Convert a prospect to retain their original history.</span></div><button class="primary" data-action="new-order">＋ New order</button></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(250px,1fr))">${d.clients.length?d.clients.map(c=>`<article class="card"><div class="row-title">${esc(c.name)}</div><div class="row-sub">${esc(c.contactName||'Client')} · ${esc(c.phone||'')}</div><div class="section-head"><span class="subtle">${d.orders.filter(o=>o.clientId===c.id).length} projects</span><span class="gold">${money(d.orders.filter(o=>o.clientId===c.id).reduce((s,o)=>s+balance(o),0))} due</span></div>${d.orders.filter(o=>o.clientId===c.id).map(o=>`<div class="row"><div><div class="row-title">${esc(o.title)}</div><div class="row-sub">${esc(o.status)} · due ${date(o.deadline)}</div></div><button class="link-btn" data-action="payment" data-id="${o.id}">Add payment</button></div>`).join('')}</article>`).join(''):empty('No clients yet','Convert an interested prospect into a client, or create a client through a conversion.','quick-add')}</div><div class="section-head"><h2>All orders</h2></div><div class="card">${d.orders.length?`<div class="list">${d.orders.map(o=>`<div class="row"><div><div class="row-title">${esc(o.title)} · ${esc(d.clients.find(c=>c.id===o.clientId)?.name||'Client')}</div><div class="row-sub">${esc(o.status)} · contracted ${money(o.price)} · balance ${money(balance(o))}</div></div><button class="link-btn" data-action="payment" data-id="${o.id}">Record payment</button></div>`).join('')}</div>`:empty('No orders recorded','Orders become confirmed contract value when you create them.')}</div>`}
function legacyFinance(d){const paid=d.payments.reduce((s,p)=>s+(+p.amount||0),0),valid=d.orders.filter(o=>o.status!=='cancelled'),contract=valid.reduce((s,o)=>s+(+o.price||0),0),out=Math.max(0,contract-paid),months={};d.payments.forEach(p=>{const m=(p.date||'').slice(0,7);if(m)months[m]=(months[m]||0)+(+p.amount||0)});const vals=Object.entries(months).sort((a,b)=>a[0].localeCompare(b[0])).slice(-8),max=Math.max(1,...vals.map(x=>x[1]));return `<div class="grid stats">${stat('Contracted value',money(contract),'Confirmed, non-cancelled orders')}${stat('Payments received',money(paid),'Recorded payments only')}${stat('Outstanding balance',money(out),'Contracted value less payments')}${stat('Paid orders',valid.filter(o=>d.payments.filter(p=>p.orderId===o.id).reduce((s,p)=>s+(+p.amount||0),0)>=+o.price).length)}${stat('Cancelled orders',d.orders.filter(o=>o.status==='cancelled').length,'Excluded from active contracted value')}${stat('Payment entries',d.payments.length)}</div><div class="grid cols"><div class="card"><h2 style="font-size:14px">Money received by month</h2><p class="subtle">Payments recorded by their payment dates.</p>${vals.length?`<div class="chart">${vals.map(([m,v])=>`<div class="bar-row"><span>${m}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><span>${money(v)}</span></div>`).join('')}</div>`:empty('No payments recorded','Record order payments to see monthly receipts.')}</div><div class="card"><h2 style="font-size:14px">Payment history</h2>${d.payments.length?`<div class="list">${[...d.payments].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(p=>`<div class="row"><div><div class="row-title">${money(p.amount)} · ${esc(p.method||'Payment')}</div><div class="row-sub">${date(p.date)} · ${esc(d.orders.find(o=>o.id===p.orderId)?.title||'Order')} · ${esc(p.note||'')}</div></div></div>`).join('')}</div>`:empty('No payments','Payments added to orders will appear here.')}</div></div><p class="subtle">Contracted value is agreed price on non-cancelled orders. Money received is the sum of recorded payments. Outstanding is the balance still due; estimates and unpaid quotes are not revenue.</p>`}
function legacyAnalytics(d){const since=new Date();since.setDate(since.getDate()-30);const cohort=d.prospects.filter(p=>new Date(p.createdAt)>=since),contact=cohort.filter(p=>p.firstContactDate||d.interactions.some(i=>i.prospectId===p.id&&['Initial message sent','Follow-up sent'].includes(i.type))),replies=cohort.filter(p=>d.interactions.some(i=>i.prospectId===p.id&&i.type==='Reply received')),won=cohort.filter(p=>p.status==='Won / client'),pct=(n,m)=>m?Math.round(n/m*100)+'%':'0%';const sources={};cohort.forEach(p=>{sources[p.source||'Other']=(sources[p.source||'Other']||0)+1});const categories={};cohort.forEach(p=>{categories[p.category||'Uncategorised']=(categories[p.category||'Uncategorised']||0)+1});const generated=d.payments.filter(p=>new Date(p.date)>=since).reduce((s,p)=>s+(+p.amount||0),0);return `<div class="card" style="margin-bottom:15px"><b>Reporting cohort: last 30 days</b><div class="row-sub">Prospects identified in the last 30 days. Reply rate = contacted cohort prospects with a reply ÷ contacted cohort prospects. Conversion = won prospects ÷ contacted cohort prospects.</div></div><div class="grid stats">${stat('Prospects identified',cohort.length)}${stat('Messages sent',d.interactions.filter(i=>new Date(i.date)>=since&&['Initial message sent','Follow-up sent'].includes(i.type)).length)}${stat('Replies received',replies.length)}${stat('Reply rate',pct(replies.length,contact.length),`${contact.length} contacted prospects`)}${stat('Interested leads',cohort.filter(p=>p.status==='Interested').length)}${stat('Clients won',won.length)}${stat('Conversion rate',pct(won.length,contact.length),`${contact.length} contacted prospects`)}${stat('Revenue received',money(generated),'Recorded payments in period')}${stat('Follow-ups completed',d.followups.filter(f=>f.completedAt&&new Date(f.completedAt)>=since).length)}</div><div class="grid cols"><div class="card"><h2 style="font-size:14px">Acquisition channels</h2>${Object.keys(sources).length?Object.entries(sources).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><span>${esc(k)}</span><span class="badge">${v}</span></div>`).join(''):empty('No cohort data','New sources will appear here.')}</div><div class="card"><h2 style="font-size:14px">Business categories</h2>${Object.keys(categories).length?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><span>${esc(k)}</span><span class="badge">${v}</span></div>`).join(''):empty('No cohort data','Categories will appear here.')}</div></div>`}
function settings(d){const s=d.settings[0]||{};return `<div class="grid cols"><section><div class="card settings-block"><h2 style="font-size:14px">Business preferences</h2><form id="settingsForm" class="form-grid"><div class="field"><label>Business name</label><input name="business" value="${esc(s.business||'KingQayumEditz')}"></div><div class="field"><label>Designer name</label><input name="designer" value="${esc(s.designer||'KingQayum')}"></div><div class="field"><label>Tagline</label><input name="tagline" value="${esc(s.tagline||'Designs that speak loud.')}"></div><div class="field"><label>Currency</label><input value="NGN · Nigerian naira" disabled></div><div class="field"><label>Default follow-up interval (days)</label><input name="interval" type="number" min="1" value="${esc(s.interval||3)}"></div><button class="primary">Save preferences</button></form></div><div class="card"><h2 style="font-size:14px">Privacy and local data</h2><p class="subtle">Records live in this browser's IndexedDB and are not encrypted by this app. Anyone with access to this browser profile may access them. Browser cleanup can remove records, so export regular backups. No cloud sync or telemetry.</p><p class="subtle">IndexedDB schema version: ${DB_VERSION}</p></div></section><section><div class="card"><h2 style="font-size:14px">Backup and restore</h2><p class="subtle">Export every store to JSON. Keep backups somewhere separate from this browser profile.</p><div class="toolbar"><button class="primary" data-action="export-json">Export JSON backup</button><label class="secondary" for="importFile">Choose backup</label><input id="importFile" class="hidden" type="file" accept="application/json,.json"></div><div class="toolbar"><button class="secondary" data-action="export-prospects">Export prospects CSV</button><button class="secondary" data-action="export-finance">Export orders and payments CSV</button></div><div id="importPreview" class="subtle"></div></div><div class="card" style="margin-top:14px"><h2 style="font-size:14px">Storage</h2><p class="subtle">Application data is local to this browser and device. An export is the portable backup.</p><button class="danger-btn" data-action="clear-data">Delete all local data</button></div></section></div>`}
function field(label,name,value='',type='text',full=false,extra=''){return `<div class="field ${full?'full':''}"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</div>`}
function selectField(label,name,options,value=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function showModal(title,body){modalRoot.innerHTML=`<div class="modal-back" data-close="yes"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}</section></div>`;modalRoot.querySelector('input,button,select')?.focus()}
function prospectForm(p={}){showModal(p.id?'Edit prospect':'Add prospect',`<form id="prospectForm" data-id="${p.id||''}"><div class="form-grid">${field('Business or prospect name *','name',p.name||'','text',true,'required')}${field('Business category','category',p.category||'')}${field('Contact person','contactName',p.contactName||'')}${field('WhatsApp number','phone',p.phone||'','tel')}${field('Facebook profile URL','facebook',p.facebook||'','url')}${field('Instagram profile URL','instagram',p.instagram||'','url')}${field('Website URL','website',p.website||'','url')}${selectField('Source channel','source',SOURCES,p.source||'Other')}${field('Source group / community','sourceGroup',p.sourceGroup||'')}${field('Date identified','identifiedDate',p.identifiedDate||today(),'date')}${field('First contact date','firstContactDate',p.firstContactDate||'','date')}${selectField('Current status','status',STATUS,p.status||'New prospect')}${selectField('Priority','priority',PRIORITIES,p.priority||'Medium')}${field('Estimated value (NGN)','estimate',p.estimate||'','number',false,'min="0" step="1"')}${field('Last contact date','lastContact',p.lastContact||'','date')}${field('Next follow-up date','nextFollowup',p.nextFollowup||'','date')}${field('Business description','description',p.description||'','textarea',true)}${field('Observed design opportunity','opportunity',p.opportunity||'','textarea',true)}${field('Proposed service','service',p.service||'')}${field('Notes','notes',p.notes||'','textarea',true)}</div><div class="modal-actions"><div>${p.id?`<button type="button" class="danger-btn" data-action="delete-prospect" data-id="${p.id}">Delete</button>`:''}</div><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Save prospect</button></div></div></form>`)}
async function detail(id){const d=await load(),p=d.prospects.find(x=>x.id===id);if(!p)return;const history=d.interactions.filter(x=>x.prospectId===id).sort((a,b)=>a.date.localeCompare(b.date)),fus=d.followups.filter(x=>x.prospectId===id&&!x.cancelled).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),client=d.clients.find(x=>x.prospectId===id),link=phoneLink(p.phone);showModal(p.name,`<div class="detail-head"><div><span class="badge">${esc(p.status)}</span> <span class="badge">${esc(p.priority||'')}</span><div class="row-sub" style="margin-top:8px">${esc(p.category||'')} · ${esc(p.source||'')}</div></div><div><button class="secondary" data-action="edit-prospect" data-id="${p.id}">Edit</button> ${client?'':`<button class="primary" data-action="convert" data-id="${p.id}">Convert to client</button>`}</div></div><div class="detail-grid">${[['Contact',p.contactName],['WhatsApp',p.phone],['Estimated value',money(p.estimate)],['Next follow-up',date(p.nextFollowup)],['Opportunity',p.opportunity],['Proposed service',p.service],['Description',p.description],['Notes',p.notes]].map(([a,b])=>`<div class="detail-item"><small>${a}</small><div>${esc(b||'—')}</div></div>`).join('')}</div><div class="toolbar">${link?`<button class="secondary" data-action="whatsapp" data-phone="${esc(p.phone)}">Review WhatsApp destination</button>`:''}<button class="secondary" data-action="copy-message" data-id="${p.id}">Copy message</button><button class="secondary" data-action="log-interaction" data-id="${p.id}">＋ Log interaction</button><button class="secondary" data-action="schedule" data-id="${p.id}">＋ Schedule follow-up</button></div><div class="section-head"><h2>Follow-ups</h2></div>${fus.length?`<div class="list">${fus.map(f=>`<div class="row"><div><div class="row-title">${date(f.dueDate)} · ${esc(f.reason||'Follow-up')}</div><div class="row-sub">${esc(f.action||'')} · ${f.completed?'Completed':'Open'}</div></div>${!f.completed?`<button class="link-btn" data-action="complete-followup" data-id="${f.id}">Complete</button>`:''}</div>`).join('')}</div>`:empty('No follow-ups','Schedule a next step to keep the conversation on track.')}<div class="section-head"><h2>Interaction history</h2></div>${history.length?`<div class="timeline">${history.map(i=>`<div class="timeline-item"><b>${esc(i.type)}</b> <span class="subtle">${date(i.date)}</span><div class="row-sub">${esc(i.summary||'')}</div>${i.nextAction?`<div class="row-sub">Next: ${esc(i.nextAction)}</div>`:''}</div>`).join('')}</div>`:empty('No interactions logged','Record activity after you contact the prospect.')}`)}
function interactionForm(id){showModal('Log interaction',`<form id="interactionForm" data-prospect="${id}"><div class="form-grid">${selectField('Type','type',['Initial message sent','Reply received','Follow-up sent','Call or conversation','Quote sent','Meeting','Order confirmed','Other'],'Initial message sent')}${field('Date','date',today(),'date')}${field('Summary','summary','','textarea',true)}${field('Optional next action','nextAction','','text',true)}</div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Save interaction</button></div></div></form>`)}
function followForm(id){showModal('Schedule follow-up',`<form id="followForm" data-prospect="${id}"><div class="form-grid">${field('Due date','dueDate',today(),'date')}${field('Reason','reason','Follow-up')}${field('Planned action','action','','text',true)}</div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Schedule</button></div></div></form>`)}
function templateForm(t={}){showModal(t.id?'Edit template':'New template',`<form id="templateForm" data-id="${t.id||''}"><div class="form-grid">${field('Template name','name',t.name||'','text',true,'required')}${field('Category','category',t.category||'Custom')}${field('Message','body',t.body||'','textarea',true,'required')}</div><p class="subtle">Placeholders: {{business_name}}, {{contact_name}}, {{service}}, {{designer_name}}</p><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Save template</button></div></div></form>`)}
function legacyOrderForm(){if(!cache.clients.length){toast('Convert a prospect to a client first.');return}showModal('Create order / project',`<form id="orderForm"><div class="form-grid">${selectField('Client','clientId',cache.clients.map(c=>c.id+'|'+c.name),cache.clients[0].id+'|'+cache.clients[0].name)}${field('Project title','title','','text',false,'required')}${field('Service category','category','Graphic design')}${field('Agreed price (NGN)','price','','number',false,'min="0" required')}${field('Deposit paid','deposit','0','number',false,'min="0"')}${field('Order date','orderDate',today(),'date')}${field('Deadline','deadline','','date')}${selectField('Status','status',['pending','in progress','awaiting client feedback','revision','completed','cancelled'],'pending')}${field('Agreed revisions','revisions','2','number')}${field('Project description','description','','textarea',true)}${field('Delivery notes','deliveryNotes','','textarea',true)}</div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Create order</button></div></div></form>`)}
function paymentForm(id){const o=cache.orders.find(x=>x.id===id),paid=cache.payments.filter(x=>x.orderId===id).reduce((s,x)=>s+(+x.amount||0),0);if(!o)return;showModal('Record payment',`<p class="subtle">${esc(o.title)} · balance ${money(Math.max(0,o.price-paid))}</p><form id="paymentForm" data-order="${id}"><div class="form-grid">${field('Amount (NGN)','amount','','number',false,`min="1" max="${Math.max(0,o.price-paid)}" required`)}${field('Payment date','date',today(),'date')}${selectField('Method','method',['Bank transfer','Cash','POS','Other'],'Bank transfer')}${field('Reference / note','note','','text',true)}</div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">Record payment</button></div></div></form>`)}
function prospects(d){const val=id=>$('#'+id)?.value||'',categories=[...new Set(d.prospects.map(p=>p.category?.trim()).filter(Boolean))].sort(),from=val('identifiedFrom'),to=val('identifiedTo'),category=val('categoryFilter');let rows=d.prospects.filter(p=>{const q=val('q').toLowerCase(),identified=p.identifiedDate||p.createdAt?.slice(0,10)||'';return(!q||`${p.name} ${p.contactName||''}`.toLowerCase().includes(q))&&(!val('fs')||p.status===val('fs'))&&(!val('fp')||p.priority===val('fp'))&&(!val('fr')||p.source===val('fr'))&&(!category||p.category===category)&&(!from||identified>=from)&&(!to||identified<=to)});const priority={High:3,Medium:2,Low:1};rows.sort((a,b)=>{switch(val('sortProspects')||'newest'){case'oldest':return a.createdAt.localeCompare(b.createdAt);case'priority':return (priority[b.priority]||0)-(priority[a.priority]||0)||b.createdAt.localeCompare(a.createdAt);case'followup':return (a.nextFollowup||'9999').localeCompare(b.nextFollowup||'9999');default:return b.createdAt.localeCompare(a.createdAt)}});let content;if(mode==='kanban')content=`<div class="kanban">${STATUS.map(s=>`<div class="kan-col"><h3>${esc(s)} · ${rows.filter(x=>x.status===s).length}</h3>${rows.filter(x=>x.status===s).map(x=>`<article class="kan-card"><button class="link-btn" data-action="detail" data-id="${x.id}">${esc(x.name)}</button><div class="row-sub">${esc(x.category||'')} · ${esc(x.priority)}</div><select data-status="${x.id}">${STATUS.map(v=>`<option ${v===x.status?'selected':''}>${esc(v)}</option>`).join('')}</select></article>`).join('')}</div>`).join('')}</div>`;else content=rows.length?`<div class="table-wrap"><table><thead><tr><th>Business</th><th>Status</th><th>Source</th><th>Category</th><th>Priority</th><th>Next follow-up</th><th>Est. value</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="row-sub">${esc(x.contactName||'')}</div></td><td><span class="badge ${x.status==='Rejected'||x.status==='Not interested'?'red':''}">${esc(x.status)}</span></td><td>${esc(x.source||'—')}</td><td>${esc(x.category||'—')}</td><td>${esc(x.priority||'—')}</td><td>${date(x.nextFollowup)}</td><td>${money(x.estimate)}</td><td><button class="link-btn" data-action="detail" data-id="${x.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching prospects','Try changing filters or add a prospect.','quick-add');return `<div class="toolbar"><input class="input search" id="q" placeholder="Search business or contact" value="${esc(val('q'))}"><select id="fs"><option value="">All statuses</option>${STATUS.map(s=>`<option ${val('fs')===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="fr"><option value="">All sources</option>${SOURCES.map(s=>`<option ${val('fr')===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="fp"><option value="">Any priority</option>${PRIORITIES.map(s=>`<option ${val('fp')===s?'selected':''}>${s}</option>`).join('')}</select><select id="categoryFilter"><option value="">All categories</option>${categories.map(s=>`<option ${category===s?'selected':''}>${esc(s)}</option>`).join('')}</select><label class="subtle">Identified <input class="input" id="identifiedFrom" aria-label="Identified from" type="date" value="${esc(from)}"> to <input class="input" id="identifiedTo" aria-label="Identified to" type="date" value="${esc(to)}"></label><select id="sortProspects" aria-label="Sort prospects"><option value="newest" ${val('sortProspects')==='newest'?'selected':''}>Newest</option><option value="oldest" ${val('sortProspects')==='oldest'?'selected':''}>Oldest</option><option value="priority" ${val('sortProspects')==='priority'?'selected':''}>Priority</option><option value="followup" ${val('sortProspects')==='followup'?'selected':''}>Next follow-up</option></select><div class="tabs"><button data-action="table" class="${mode==='table'?'active':''}">Table</button><button data-action="kanban" class="${mode==='kanban'?'active':''}">Pipeline</button></div></div>${content}`}
function clients(d){const val=id=>$('#'+id)?.value||'',clientFilter=val('clientFilter'),statusFilter=val('orderStatusFilter'),q=val('clientSearch').toLowerCase(),clientsRows=d.clients.filter(c=>(!clientFilter||c.id===clientFilter)&&(!q||`${c.name} ${c.contactName||''}`.toLowerCase().includes(q))),orderRows=d.orders.filter(o=>(!clientFilter||o.clientId===clientFilter)&&(!statusFilter||o.status===statusFilter));const balance=o=>Math.max(0,+o.price-d.payments.filter(p=>p.orderId===o.id).reduce((s,p)=>s+(+p.amount||0),0));return `<div class="section-head"><div><h2>Clients and active orders</h2><span class="subtle">Convert a prospect to retain its history. Filter clients and projects below.</span></div><button class="primary" data-action="new-order">＋ New order</button></div><div class="toolbar"><input class="input search" id="clientSearch" placeholder="Search clients" value="${esc(q)}"><select id="clientFilter"><option value="">All clients</option>${d.clients.map(c=>`<option value="${c.id}" ${clientFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="orderStatusFilter"><option value="">All project statuses</option>${['pending','in progress','awaiting client feedback','revision','completed','cancelled'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(250px,1fr))">${clientsRows.length?clientsRows.map(c=>`<article class="card"><div class="row-title">${esc(c.name)}</div><div class="row-sub">${esc(c.contactName||'Client')} · ${esc(c.phone||'')}</div><div class="section-head"><span class="subtle">${d.orders.filter(o=>o.clientId===c.id).length} projects</span><span class="gold">${money(d.orders.filter(o=>o.clientId===c.id).reduce((s,o)=>s+balance(o),0))} due</span></div></article>`).join(''):empty('No matching clients','Convert a prospect or adjust your client filter.')}</div><div class="section-head"><h2>Orders</h2></div><div class="card">${orderRows.length?`<div class="list">${orderRows.map(o=>`<div class="row"><div><div class="row-title">${esc(o.title)} · ${esc(d.clients.find(c=>c.id===o.clientId)?.name||'Client')}</div><div class="row-sub">${esc(o.status)} · contracted ${money(o.price)} · balance ${money(balance(o))} · due ${date(o.deadline)}</div>${d.payments.filter(p=>p.orderId===o.id).map(p=>`<div class="row-sub">Payment: ${date(p.date)} · ${money(p.amount)} · ${esc(p.method||'')}</div>`).join('')}</div><div><button class="link-btn" data-action="edit-order" data-id="${o.id}">Edit</button> <button class="link-btn" data-action="payment" data-id="${o.id}">Record payment</button></div></div>`).join('')}</div>`:empty('No orders match','Create an order or adjust filters.')}</div>`}
function finance(d){const val=id=>$('#'+id)?.value||'',clientId=val('financeClient'),from=val('financeFrom'),to=val('financeTo'),orders=d.orders.filter(o=>(!clientId||o.clientId===clientId)&&(!from||(o.orderDate||'')>=from)&&(!to||(o.orderDate||'')<=to)),ids=new Set(orders.map(o=>o.id)),payments=d.payments.filter(p=>ids.has(p.orderId)&&(!from||(p.date||'')>=from)&&(!to||(p.date||'')<=to)),active=orders.filter(o=>o.status!=='cancelled'),paid=payments.reduce((s,p)=>s+(+p.amount||0),0),contract=active.reduce((s,o)=>s+(+o.price||0),0),out=active.reduce((s,o)=>Math.max(0,+o.price-d.payments.filter(p=>p.orderId===o.id).reduce((a,p)=>a+(+p.amount||0),0)),0),months={};payments.forEach(p=>{const m=(p.date||'').slice(0,7);if(m)months[m]=(months[m]||0)+(+p.amount||0)});const vals=Object.entries(months).sort((a,b)=>a[0].localeCompare(b[0])).slice(-12),max=Math.max(1,...vals.map(x=>x[1]));return `<div class="toolbar"><select id="financeClient"><option value="">All clients</option>${d.clients.map(c=>`<option value="${c.id}" ${clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label class="subtle">Order date from <input class="input" id="financeFrom" type="date" value="${esc(from)}"></label><label class="subtle">to <input class="input" id="financeTo" type="date" value="${esc(to)}"></label><span class="subtle">Balances always use all payments on the selected orders.</span></div><div class="grid stats">${stat('Contracted value',money(contract),'Selected non-cancelled orders')}${stat('Payments received',money(paid),'Selected dates, clients and orders')}${stat('Outstanding balance',money(out),'Current remaining balance on selected orders')}${stat('Paid orders',active.filter(o=>d.payments.filter(p=>p.orderId===o.id).reduce((s,p)=>s+(+p.amount||0),0)>=+o.price).length)}${stat('Cancelled orders',orders.filter(o=>o.status==='cancelled').length,'Separated from contracted value')}${stat('Payment entries',payments.length)}</div><div class="grid cols"><div class="card"><h2 style="font-size:14px">Payments by month</h2><p class="subtle">Recorded payment dates in selected period.</p>${vals.length?`<div class="chart">${vals.map(([m,v])=>`<div class="bar-row"><span>${m}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><span>${money(v)}</span></div>`).join('')}</div>`:empty('No payments in this selection','Adjust filters or record payments.')}</div><div class="card"><h2 style="font-size:14px">Payment history</h2>${payments.length?`<div class="list">${[...payments].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(p=>`<div class="row"><div><div class="row-title">${money(p.amount)} · ${esc(p.method||'Payment')}</div><div class="row-sub">${date(p.date)} · ${esc(d.orders.find(o=>o.id===p.orderId)?.title||'Order')} · ${esc(d.clients.find(c=>c.id===d.orders.find(o=>o.id===p.orderId)?.clientId)?.name||'')} · ${esc(p.note||'')}</div></div></div>`).join('')}</div>`:empty('No payments','Recorded payments appear here.')}</div></div><p class="subtle">Contracted value is agreed price for selected non-cancelled orders. Received is payment entries within the selected payment date range. Outstanding is current order balance and uses all payments recorded against those orders. Quotations are excluded.</p>`}
const defaultTemplates=[['First-contact message','First contact','Hello {{contact_name}}, I’m {{designer_name}} from KingQayumEditz. I came across {{business_name}} and noticed an opportunity to strengthen its visual identity. I offer {{service}} and would be happy to share a few ideas if useful.'],['Interested prospect response','Interested','Thanks for your interest, {{contact_name}}. I’d be glad to help {{business_name}} with {{service}}. What would you like the design to achieve?'],['Follow-up after no reply','Follow-up','Hello {{contact_name}}, just following up on my note about {{service}} for {{business_name}}. No rush—if it is useful, I can share a few ideas.'],['Future opportunity','Future opportunity','Thanks for letting me know, {{contact_name}}. I understand. I’ll leave it with you, and you’re welcome to reach out whenever {{business_name}} needs {{service}}.'],['Price quotation','Quotation','Hello {{contact_name}}, for {{service}} for {{business_name}}, the quoted fee is NGN [amount]. This includes [deliverables]. Let me know if you would like me to clarify anything.'],['Project confirmation','Confirmation','Hello {{contact_name}}, confirming the {{service}} project for {{business_name}}. Agreed fee: NGN [amount]. Timeline: [timeline]. I’ll begin once the agreed deposit is received.'],['Payment reminder','Payment','Hello {{contact_name}}, a gentle reminder that NGN [balance] is due for the {{service}} project. Please let me know if you need the invoice or payment details again.'],['Post-delivery thank-you','Thank you','Thank you for choosing KingQayumEditz, {{contact_name}}. I hope the {{service}} works beautifully for {{business_name}}. I appreciate your trust.'],['Repeat-client outreach','Repeat client','Hello {{contact_name}}, hope all is well at {{business_name}}. I’m available if you need any new {{service}} or design support. Happy to discuss whenever convenient.']];
function orderForm(existing={}){if(!cache.clients.length){toast('Convert a prospect to a client first.');return}const statuses=['pending','in progress','awaiting client feedback','revision','completed','cancelled'];showModal(existing.id?'Edit order / project':'Create order / project',`<form id="orderForm" data-id="${existing.id||''}"><div class="form-grid">${selectField('Client','clientId',cache.clients.map(c=>c.id+'|'+c.name),(existing.clientId||cache.clients[0].id)+'|'+(cache.clients.find(c=>c.id===(existing.clientId||cache.clients[0].id))?.name||''))}${field('Project title','title',existing.title||'','text',false,'required')}${field('Service category','category',existing.category||'Graphic design')}${field('Agreed price (NGN)','price',existing.price??'','number',false,'min="0" required')}${existing.id?`<div class="field"><label>Payments already recorded</label><input value="${esc(money(cache.payments.filter(p=>p.orderId===existing.id).reduce((s,p)=>s+(+p.amount||0),0)))}" disabled></div>`:field('Deposit paid','deposit','0','number',false,'min="0"')}${field('Order date','orderDate',existing.orderDate||today(),'date')}${field('Deadline','deadline',existing.deadline||'','date')}${selectField('Status','status',statuses,existing.status||'pending')}${field('Agreed revisions','revisions',existing.revisions??2,'number')}${field('Project description','description',existing.description||'','textarea',true)}${field('Delivery notes','deliveryNotes',existing.deliveryNotes||'','textarea',true)}</div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">${existing.id?'Save changes':'Create order'}</button></div></div></form>`)}
function analytics(d){const now=new Date(),since=new Date(now);since.setDate(since.getDate()-30);const iso=x=>x instanceof Date?x.toISOString().slice(0,10):String(x||'').slice(0,10),start=iso(since),end=iso(now),cohort=d.prospects.filter(p=>(p.identifiedDate||iso(p.createdAt))>=start&&(p.identifiedDate||iso(p.createdAt))<=end),sentTypes=['Initial message sent','Follow-up sent'],sent=d.interactions.filter(i=>i.date>=start&&i.date<=end&&sentTypes.includes(i.type)),sentIds=new Set(sent.map(i=>i.prospectId)),replyIds=new Set(d.interactions.filter(i=>i.date>=start&&i.date<=end&&i.type==='Reply received').map(i=>i.prospectId)),contacted=cohort.filter(p=>sentIds.has(p.id)||p.firstContactDate>=start&&p.firstContactDate<=end),replies=contacted.filter(p=>replyIds.has(p.id)),wonIds=new Set(d.clients.filter(c=>c.createdAt?.slice(0,10)>=start&&c.createdAt?.slice(0,10)<=end).map(c=>c.prospectId)),won=contacted.filter(p=>wonIds.has(p.id)),pct=(n,m)=>m?Math.round(n/m*100)+'%':'0%',sources={},categories={};cohort.forEach(p=>{const source=p.source||'Other',s=sources[source]||(sources[source]={identified:0,contacted:0,won:0});s.identified++;if(contacted.some(c=>c.id===p.id))s.contacted++;if(wonIds.has(p.id))s.won++;const cat=p.category||'Uncategorised';categories[cat]=(categories[cat]||0)+1});const generated=d.payments.filter(p=>p.date>=start&&p.date<=end).reduce((s,p)=>s+(+p.amount||0),0);return `<div class="card" style="margin-bottom:15px"><b>Reporting period: ${date(start)} – ${date(end)}</b><div class="row-sub">Cohort is prospects identified in the last 30 days. Contacted means a first contact or outreach recorded in this period. Reply rate is contacted cohort prospects with a reply in the period divided by contacted cohort. Conversion is contacted cohort prospects converted in the period divided by contacted cohort. Channel performance shows contacted cohort conversions.</div></div><div class="grid stats">${stat('Prospects identified',cohort.length)}${stat('Messages sent',sent.length)}${stat('Replies received',replies.length)}${stat('Reply rate',pct(replies.length,contacted.length),`${contacted.length} contacted prospects`)}${stat('Interested leads',cohort.filter(p=>p.status==='Interested').length)}${stat('Clients won',won.length)}${stat('Conversion rate',pct(won.length,contacted.length),`${contacted.length} contacted prospects`)}${stat('Revenue received',money(generated),'Recorded payments in period')}${stat('Follow-ups completed',d.followups.filter(f=>f.completedAt&&f.completedAt.slice(0,10)>=start&&f.completedAt.slice(0,10)<=end).length)}</div><div class="grid cols"><div class="card"><h2 style="font-size:14px">Acquisition channel performance</h2>${Object.keys(sources).length?Object.entries(sources).sort((a,b)=>b[1].won-a[1].won||b[1].identified-a[1].identified).map(([k,v])=>`<div class="row"><span>${esc(k)} · ${v.identified} identified</span><span class="badge">${v.won} won / ${v.contacted} contacted · ${pct(v.won,v.contacted)}</span></div>`).join(''):empty('No cohort data','New sources will appear here.')}</div><div class="card"><h2 style="font-size:14px">Business categories</h2>${Object.keys(categories).length?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><span>${esc(k)}</span><span class="badge">${v}</span></div>`).join(''):empty('No cohort data','Categories will appear here.')}</div></div>`}
async function seed(){if(!(await all('templates')).length)for(const [name,category,body] of defaultTemplates)await put('templates',make({name,category,body}));if(!(await all('settings')).length)await put('settings',make({business:'KingQayumEditz',designer:'KingQayum',tagline:'Designs that speak loud.',currency:'NGN',interval:3}))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="edit-order"]');if(b){e.preventDefault();e.stopImmediatePropagation();const o=cache.orders.find(x=>x.id===b.dataset.id);if(o)orderForm(o)}const imp=e.target.closest('[data-action="merge-import"],[data-action="replace-import"]');if(imp&&window._pendingImport){try{validateBackupData(window._pendingImport,cache,imp.dataset.action==='replace-import')}catch(err){e.preventDefault();e.stopImmediatePropagation();toast('Import rejected: '+err.message)}}},true);
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='orderForm'||!f.dataset.id)return;e.preventDefault();e.stopImmediatePropagation();const b=f.querySelector('button.primary');if(b.disabled)return;b.disabled=true;const v=Object.fromEntries(new FormData(f).entries()),old=cache.orders.find(x=>x.id===f.dataset.id),[clientId]=v.clientId.split('|'),price=+v.price,paid=cache.payments.filter(p=>p.orderId===old.id).reduce((s,p)=>s+(+p.amount||0),0);try{if(!old)throw Error('Order no longer exists.');if(!Number.isFinite(price)||price<paid||price<0)throw Error('Agreed price cannot be lower than payments already recorded.');await put('orders',{...old,...v,clientId,price,revisions:Math.max(0,+v.revisions||0),updatedAt:stamp()});modalRoot.innerHTML='';toast('Order updated');render()}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=false}},true);
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render();$('#sidebar').classList.remove('open')}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='dmStudioForm')return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button.primary');if(button.disabled)return;button.disabled=true;try{await generateFromForm(cache);await render()}catch(err){console.error(err);toast(err.message||'Could not generate a draft')}finally{if(button.isConnected)button.disabled=false}},true);
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!['dm-copy','dm-regenerate','dm-save-template','dm-record'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();try{if(action==='dm-copy'){syncDraftFromEditor();await copyDraft();toast('Draft copied. It has not been sent or recorded.')}if(action==='dm-regenerate'){await generateFromForm(cache);await render()}if(action==='dm-save-template'){syncDraftFromEditor();await saveDraftTemplate();toast('Draft saved to Message library.');await render()}if(action==='dm-record'){syncDraftFromEditor();if(await recordDraft()){toast('Interaction recorded after your confirmation.');await render()}}}catch(err){console.error(err);toast(err.message||'Could not complete DM Studio action')}},true);
$('#view').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render()}});
$('#view').addEventListener('input',e=>{if(['q','clientSearch','identifiedFrom','identifiedTo','financeFrom','financeTo'].includes(e.target.id))render()});$('#view').addEventListener('change',e=>{if(['fs','fp','fr','categoryFilter','sortProspects','identifiedFrom','identifiedTo','clientSearch','clientFilter','orderStatusFilter','financeClient','financeFrom','financeTo'].includes(e.target.id))render();if(e.target.dataset.status)changeStatus(e.target.dataset.status,e.target.value);if(e.target.id==='importFile')previewImport(e.target.files[0])});
document.addEventListener('click',async e=>{const n=e.target.closest('[data-action]');if(!n)return;const a=n.dataset.action,id=n.dataset.id;try{switch(a){case'quick-add':prospectForm();break;case'table':mode='table';render();break;case'kanban':mode='kanban';render();break;case'detail':detail(id);break;case'close-modal':modalRoot.innerHTML='';break;case'edit-prospect':modalRoot.innerHTML='';prospectForm(cache.prospects.find(p=>p.id===id));break;case'delete-prospect':if(confirm('Delete this prospect and its interactions and follow-ups? This cannot be undone.')){await batch([...cache.interactions.filter(i=>i.prospectId===id).map(i=>({store:'interactions',op:'delete',id:i.id})),...cache.followups.filter(f=>f.prospectId===id).map(f=>({store:'followups',op:'delete',id:f.id})),{store:'prospects',op:'delete',id}]);modalRoot.innerHTML='';toast('Prospect deleted');render()}break;case'log-interaction':interactionForm(id);break;case'schedule':followForm(id);break;case'complete-followup':{const f=cache.followups.find(x=>x.id===id);await put('followups',{...f,completed:true,completedAt:stamp(),updatedAt:stamp()});toast('Follow-up completed');render();if($('#modalRoot').innerHTML.includes('role="dialog"'))detail(f.prospectId);break}case'cancel-followup':{const f=cache.followups.find(x=>x.id===id);await put('followups',{...f,cancelled:true,updatedAt:stamp()});render()}break;case'reschedule':{const f=cache.followups.find(x=>x.id===id),d=prompt('New due date (YYYY-MM-DD)',f.dueDate);if(d&&/^\d{4}-\d{2}-\d{2}$/.test(d))await put('followups',{...f,dueDate:d,updatedAt:stamp()});render()}break;case'convert':{const p=cache.prospects.find(x=>x.id===id);if(cache.clients.some(c=>c.prospectId===id)){toast('Already converted');break}const c=make({prospectId:id,name:p.name,contactName:p.contactName,phone:p.phone,email:p.email});await batch([{store:'clients',item:c},{store:'prospects',item:{...p,status:'Won / client',convertedAt:stamp(),updatedAt:stamp()}}]);toast('Converted to client; prospect history retained');detail(id);break}case'new-order':orderForm();break;case'payment':paymentForm(id);break;case'new-template':templateForm();break;case'edit-template':templateForm(cache.templates.find(x=>x.id===id));break;case'duplicate-template':{const t=cache.templates.find(x=>x.id===id);await put('templates',make({...t,id:uid(),name:t.name+' copy'}));render();toast('Template duplicated');break}case'delete-template':if(confirm('Delete this template?')){await remove('templates',id);render()}break;case'export-json':download('kingqayum-crm-backup-'+today()+'.json',JSON.stringify(await dump(),null,2));break;case'export-prospects':download('kingqayum-prospects-'+today()+'.csv',csv(cache.prospects,[{label:'Business',value:'name'},{label:'Contact',value:'contactName'},{label:'Status',value:'status'},{label:'Source',value:'source'},{label:'Phone',value:'phone'},{label:'Priority',value:'priority'},{label:'Estimate NGN',value:'estimate'},{label:'Follow-up',value:'nextFollowup'}]),'text/csv');break;case'export-finance':download('kingqayum-finance-'+today()+'.csv',csv([...cache.orders.map(o=>({...o,rowType:'Order'})),...cache.payments.map(p=>({...p,rowType:'Payment'}))],[{label:'Type',value:'rowType'},{label:'Title/order',value:r=>r.title||r.orderId},{label:'Date',value:r=>r.date||r.orderDate},{label:'Amount NGN',value:r=>r.price??r.amount},{label:'Status',value:'status'},{label:'Note',value:r=>r.note||r.deliveryNotes}]),'text/csv');break;case'clear-data':if(confirm('Permanently delete all local CRM records? Export a backup first.')){await replaceAll(Object.fromEntries(STORES.map(s=>[s,[]])));await seed();toast('Local records deleted');render()}break;case'whatsapp':{const url=phoneLink(n.dataset.phone);if(url&&confirm(`Open WhatsApp chat for ${url}? Review the number before continuing.`))window.open(url,'_blank','noopener');else if(!url)toast('Could not normalize this number.');break}case'copy-message':templatePicker(id);break}}
catch(err){console.error(err);toast('Could not complete action: '+err.message)}});
$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#themeBtn').addEventListener('click',()=>{document.body.classList.toggle('light');localStorage.setItem('theme',document.body.classList.contains('light')?'light':'dark')});if(localStorage.getItem('theme')==='light')document.body.classList.add('light');
async function changeStatus(id,status){const p=cache.prospects.find(x=>x.id===id);if(!p)return;const upd={...p,status,updatedAt:stamp()};if(status==='Won / client'&&!cache.clients.some(c=>c.prospectId===id)){if(confirm('Convert this prospect to a client and preserve its history?')){await batch([{store:'prospects',item:upd},{store:'clients',item:make({prospectId:id,name:p.name,contactName:p.contactName,phone:p.phone})}])}else{await put('prospects',{...p,status:p.status})}}else await put('prospects',upd);render()}
function templatePicker(id){const opts=cache.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');showModal('Copy a personalized message',`<form id="copyForm" data-prospect="${id}"><div class="form-grid">${selectField('Template','template',cache.templates.map(t=>t.id+'|'+t.name),(cache.templates[0]?.id||'')+'|'+(cache.templates[0]?.name||''))}<div class="field"><label>Personalized preview</label><textarea id="previewText" readonly></textarea></div></div><div class="modal-actions"><span></span><div><button type="button" class="secondary" data-action="close-modal">Close</button><button class="primary">Copy message</button></div></div></form>`);const f=cache.prospects.find(x=>x.id===id),sel=$('#copyForm select');const update=()=>{const t=cache.templates.find(x=>x.id===sel.value.split('|')[0]);$('#previewText').value=t?t.body.replaceAll('{{business_name}}',f.name||'').replaceAll('{{contact_name}}',f.contactName||'there').replaceAll('{{service}}',f.service||'design services').replaceAll('{{designer_name}}',cache.settings[0]?.designer||'KingQayum'):''};sel.addEventListener('change',update);update()}
function validateBackupData(data,current,replace=false){if(!data||!STORES.every(s=>Array.isArray(data[s])))throw Error('Backup must contain arrays for all stores.');const ids={};for(const s of STORES){ids[s]=new Set();for(const x of data[s]){if(!x||typeof x!=='object'||Array.isArray(x)||typeof x.id!=='string'||!x.id.trim())throw Error(`${s} contains a record without a valid ID.`);if(ids[s].has(x.id))throw Error(`${s} contains duplicate IDs.`);ids[s].add(x.id)}}const exists=(store,id)=>ids[store].has(id)||(!replace&&current[store].some(x=>x.id===id));for(const x of data.prospects)if(x.estimate!==undefined&&(!Number.isFinite(+x.estimate)||+x.estimate<0))throw Error('Prospect estimate is invalid.');for(const x of data.orders){if(!Number.isFinite(+x.price)||+x.price<0)throw Error('An order has an invalid agreed price.');if(!exists('clients',x.clientId))throw Error('An order references a missing client.')}for(const x of data.payments){if(!Number.isFinite(+x.amount)||+x.amount<=0)throw Error('A payment amount must be greater than zero.');if(!exists('orders',x.orderId))throw Error('A payment references a missing order.')}for(const s of ['interactions','followups'])for(const x of data[s])if(!exists('prospects',x.prospectId))throw Error(`A ${s==='interactions'?'interaction':'follow-up'} references a missing prospect.`);for(const x of data.clients)if(x.prospectId&&!exists('prospects',x.prospectId))throw Error('A client references a missing prospect.');return data}
async function previewImport(file){if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.schemaVersion!==undefined&&(!Number.isInteger(raw.schemaVersion)||raw.schemaVersion<1||raw.schemaVersion>DB_VERSION))throw Error('Backup schema version is not supported.');const data=raw.data||raw,d=await load();validateBackupData(data,d);const counts=Object.fromEntries(STORES.map(s=>[s,data[s].length]));const incoming=STORES.reduce((n,s)=>n+data[s].length,0),dupes=STORES.reduce((n,s)=>n+data[s].filter(x=>d[s].some(y=>y.id===x.id)).length,0);$('#importPreview').innerHTML=`<p>Validated backup · ${incoming} records across stores · ${dupes} matching IDs</p><p>${STORES.map(s=>`${s}: ${counts[s]}`).join(' · ')}</p><button class="secondary" data-action="merge-import">Merge backup</button> <button class="danger-btn" data-action="replace-import">Replace all local data</button>`;window._pendingImport=data;toast('Backup validated; choose merge or replace explicitly.')}catch(e){$('#importPreview').textContent='Import rejected: '+e.message;window._pendingImport=null}}
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!['merge-import','replace-import'].includes(a))return;try{const data=window._pendingImport;if(!data)throw Error('Select a valid backup first.');if(a==='replace-import'){if(!confirm('Replace all current records with this backup? This cannot be undone.'))return;await replaceAll(data)}else{const maps={};for(const s of STORES)maps[s]=new Map();for(const s of STORES)for(const x of data[s]||[])if(cache[s].some(y=>y.id===x.id))maps[s].set(x.id,uid());const rows=[];for(const s of STORES)for(let x of data[s]||[]){x={...x,id:maps[s].get(x.id)||x.id};if(s==='interactions'||s==='followups')x.prospectId=maps.prospects.get(x.prospectId)||x.prospectId;if(s==='clients')x.prospectId=maps.prospects.get(x.prospectId)||x.prospectId;if(s==='orders')x.clientId=maps.clients.get(x.clientId)||x.clientId;if(s==='payments')x.orderId=maps.orders.get(x.orderId)||x.orderId;rows.push({store:s,item:x})}await batch(rows)}window._pendingImport=null;toast('Backup restored');render()}catch(err){toast('Import failed: '+err.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['prospectForm','interactionForm','followForm','templateForm','orderForm','paymentForm','settingsForm','copyForm'].includes(form.id))return;e.preventDefault();const b=form.querySelector('button.primary');if(b.disabled)return;b.disabled=true;const fd=new FormData(form),v=Object.fromEntries(fd.entries());try{switch(form.id){case'prospectForm':{if(!v.name.trim())throw Error('Business name is required.');const old=cache.prospects.find(x=>x.id===form.dataset.id);if(!old&&cache.prospects.some(x=>x.name.trim().toLowerCase()===v.name.trim().toLowerCase()&&(!v.phone||x.phone===v.phone))){if(!confirm('A prospect with this business name and contact already exists. Add another anyway?'))break}const item={...old,...v,name:v.name.trim(),estimate:Math.max(0,+v.estimate||0),updatedAt:stamp()};await put('prospects',old?item:make(item));modalRoot.innerHTML='';toast(old?'Prospect updated':'Prospect saved');render();break}case'interactionForm':{const i=make({...v,prospectId:form.dataset.prospect});await put('interactions',i);const p=cache.prospects.find(x=>x.id===i.prospectId);await put('prospects',{...p,lastContact:v.date,firstContactDate:p.firstContactDate||(['Initial message sent','Follow-up sent'].includes(v.type)?v.date:p.firstContactDate),status:v.type==='Reply received'?'Interested':(['Initial message sent','Follow-up sent'].includes(v.type)&&p.status==='New prospect'?'Contacted':p.status),updatedAt:stamp()});modalRoot.innerHTML='';detail(i.prospectId);toast('Interaction saved');break}case'followForm':{const p=cache.prospects.find(x=>x.id===form.dataset.prospect);const f=make({...v,prospectId:p.id,completed:false,cancelled:false});const rows=[{store:'followups',item:f},{store:'prospects',item:{...p,nextFollowup:v.dueDate,updatedAt:stamp()}}];await batch(rows);modalRoot.innerHTML='';detail(p.id);toast('Follow-up scheduled');break}case'templateForm':{const old=cache.templates.find(x=>x.id===form.dataset.id);await put('templates',old?{...old,...v,updatedAt:stamp()}:make(v));modalRoot.innerHTML='';render();toast('Template saved');break}case'orderForm':{const [clientId]=v.clientId.split('|'),price=+v.price,deposit=+v.deposit||0;if(price<0||deposit<0||deposit>price)throw Error('Payments must be nonnegative and no greater than the agreed price.');const o=make({...v,clientId,price,deposit:0,revisions:+v.revisions||0});const rows=[{store:'orders',item:o}];if(deposit>0)rows.push({store:'payments',item:make({orderId:o.id,amount:deposit,date:v.orderDate,method:'Deposit',note:'Initial deposit'})});await batch(rows);modalRoot.innerHTML='';render();toast('Order created');break}case'paymentForm':{const o=cache.orders.find(x=>x.id===form.dataset.order),paid=cache.payments.filter(x=>x.orderId===o.id).reduce((s,x)=>s+(+x.amount||0),0),amt=+v.amount;if(!(amt>0)||amt>Math.max(0,+o.price-paid))throw Error('Payment must be positive and cannot exceed the remaining balance.');await put('payments',make({...v,amount:amt,orderId:o.id}));modalRoot.innerHTML='';render();toast('Payment recorded');break}case'settingsForm':await put('settings',{...(cache.settings[0]||make({})),...v,interval:Math.max(1,+v.interval||3),updatedAt:stamp()});toast('Preferences saved');break;case'copyForm':await navigator.clipboard.writeText($('#previewText').value);modalRoot.innerHTML='';toast('Message copied; send it yourself when ready.');break}}catch(err){console.error(err);toast(err.message||'Could not save')}finally{if(b.isConnected)b.disabled=false}});
window.addEventListener('error',e=>{console.error(e.error);toast('Something went wrong. Your saved records are unchanged.')});
